/* @autogenerated */
package net.civeira.phylax.features.oauth.userinvitation.application;

import java.util.List;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.security.impl.ActorImpl;

class InvitationAdminPolicyUnitTest {

  private static ActorImpl actor(boolean authenticated, String tenant, List<String> roles,
      List<String> scopes) {
    return ActorImpl.builder().authenticated(authenticated).uid("admin").name("admin")
        .tenant(tenant).roles(roles).groups(List.of()).scopes(scopes).build();
  }

  @Test
  @DisplayName("An admin of the tenant manages its invitations")
  void tenant_admin() {
    Assertions.assertTrue(InvitationAdminPolicy
        .allows(actor(true, "uid-a", List.of("admin"), List.of()), "uid-a", "tenant-a"));
    Assertions.assertTrue(InvitationAdminPolicy
        .allows(actor(true, "tenant-a", List.of("admin"), List.of()), "uid-a", "tenant-a"));
  }

  @Test
  @DisplayName("An admin of another tenant, a non admin or an anonymous caller does not")
  void others() {
    Assertions.assertFalse(InvitationAdminPolicy
        .allows(actor(true, "uid-b", List.of("admin"), List.of()), "uid-a", "tenant-a"));
    Assertions.assertFalse(InvitationAdminPolicy
        .allows(actor(true, "uid-a", List.of("user"), List.of()), "uid-a", "tenant-a"));
    Assertions.assertFalse(InvitationAdminPolicy
        .allows(actor(false, "uid-a", List.of("admin"), List.of()), "uid-a", "tenant-a"));
    Assertions.assertFalse(InvitationAdminPolicy.allows(null, "uid-a", "tenant-a"));
  }

  @Test
  @DisplayName("A root admin manages every tenant")
  void root() {
    Assertions.assertTrue(InvitationAdminPolicy.allows(
        actor(true, "root", List.of("admin"), List.of("platform:global_access")), "uid-a",
        "tenant-a"));
  }
}
